import { getContext, setContext } from 'svelte';
const key = Symbol('mizu-combobox');
type ComboboxContext = {
	readonly open: boolean;
	/** The chosen value, so the input can carry a fresh pick in from the list. */
	readonly value: string | string[] | undefined;
	contentId: string | undefined;
};
export const setComboboxContext = (context: ComboboxContext) => setContext(key, context);
export const getComboboxContext = () => getContext<ComboboxContext | undefined>(key);

import type { Attachment } from 'svelte/attachments';
import { prefersReducedMotion } from '$lib/components/ui/motion';

// Command and Combobox each carry an identical copy of this file on purpose,
// so each registry item installs on its own without depending on the other.
// Change both together.

/**
 * One highlight for the whole list that glides from row to row, so moving
 * through results reads as a single thing travelling rather than rows
 * blinking on and off. Attach to the positioned element that holds both the
 * items and a `[data-highlight-pill]` element; the pill is moved under
 * whichever item matches `highlighted`. When the list is rebuilt (opened or
 * filtered) the pill lands in place instead of sliding from its last spot.
 */
export function highlightGlide(highlighted: string): Attachment<HTMLElement> {
	return (container) => {
		const pill = container.querySelector<HTMLElement>(':scope > [data-highlight-pill]');
		if (!pill) return;
		container.setAttribute('data-highlight-glide', '');

		let shown = false;
		let rebuilt = true;

		const move = () => {
			const item = container.querySelector<HTMLElement>(highlighted);
			if (!item || !item.offsetHeight) {
				shown = false;
				pill.style.opacity = '0';
				return;
			}
			const jump = !shown || rebuilt || prefersReducedMotion();
			rebuilt = false;
			shown = true;
			if (jump) pill.style.transition = 'none';
			pill.style.translate = `${item.offsetLeft}px ${item.offsetTop}px`;
			pill.style.width = `${item.offsetWidth}px`;
			pill.style.height = `${item.offsetHeight}px`;
			pill.style.opacity = '1';
			if (jump) {
				// Commits the jump before the transition comes back.
				void pill.offsetHeight;
				pill.style.removeProperty('transition');
			}
		};

		const observer = new MutationObserver((records) => {
			if (records.some((record) => record.type === 'childList')) rebuilt = true;
			move();
		});
		observer.observe(container, {
			subtree: true,
			childList: true,
			attributes: true,
			attributeFilter: ['data-highlighted', 'data-selected', 'aria-selected', 'hidden']
		});
		// The list can settle its width after it opens; re-measure in place.
		const resize = new ResizeObserver(() => {
			rebuilt = true;
			move();
		});
		resize.observe(container);
		move();

		return () => {
			observer.disconnect();
			resize.disconnect();
			container.removeAttribute('data-highlight-glide');
		};
	};
}

import { Combobox as ComboboxPrimitive } from 'bits-ui';

import Input from './combobox-input.svelte';
import Trigger from './combobox-trigger.svelte';
import Content from './combobox-content.svelte';
import Item from './combobox-item.svelte';
import Group from './combobox-group.svelte';
import GroupHeading from './combobox-group-heading.svelte';

import Root from './combobox.svelte';
const Portal = ComboboxPrimitive.Portal;

export {
	Root,
	Input,
	Trigger,
	Portal,
	Content,
	Item,
	Group,
	GroupHeading,
	//
	Root as Combobox,
	Input as ComboboxInput,
	Trigger as ComboboxTrigger,
	Portal as ComboboxPortal,
	Content as ComboboxContent,
	Item as ComboboxItem,
	Group as ComboboxGroup,
	GroupHeading as ComboboxGroupHeading
};

import type { Attachment } from 'svelte/attachments';

// Select and Combobox each carry an identical copy of this file on purpose,
// so each registry item installs on its own without depending on the other.
// Change both together.

/**
 * Keeps a list that scrolls reachable by keyboard. While the viewport
 * overflows it joins the tab order as a group of the listbox, so the region
 * can be focused and scrolled; a list that fits stays out of the way. Arrow
 * keys, typeahead, and the highlighted option are still handled by the list.
 */
export const scrollReach: Attachment<HTMLElement> = (viewport) => {
	const initialRole = viewport.getAttribute('role');
	const update = () => {
		const scrolls = viewport.scrollHeight > viewport.clientHeight + 1;
		if (scrolls) {
			viewport.setAttribute('tabindex', '0');
			viewport.setAttribute('role', 'group');
		} else {
			viewport.removeAttribute('tabindex');
			if (initialRole === null) viewport.removeAttribute('role');
			else viewport.setAttribute('role', initialRole);
		}
	};
	update();
	if (typeof ResizeObserver === 'undefined') return;
	// The viewport resizes with its cap; its children resize as options come and go.
	const resizes = new ResizeObserver(update);
	const observe = () => {
		resizes.disconnect();
		resizes.observe(viewport);
		for (const child of viewport.children) resizes.observe(child);
	};
	const mutations = new MutationObserver(() => {
		observe();
		update();
	});
	mutations.observe(viewport, { childList: true });
	observe();
	return () => {
		resizes.disconnect();
		mutations.disconnect();
	};
};
